#!/usr/bin/env node
// Generate server/lib/doLines.json from docs/do-lines-review.md.
//
//   node scripts/buildDoLines.js
//
// WHY THIS FILE EXISTS: THE DEPLOY BOUNDARY. Railway's Root Directory is `server/`, so
// nothing outside it reaches production. Both the counter's card projection and its ask
// pipeline read the reviewed `do` lines from `docs/`, wrapped in a try/catch that fell
// back to an empty Map — so in production every curated card served by /api/counter/ask
// had an EMPTY do line. The do line is the whole point of the card, and asking is the
// lead interaction on the Counter. It had been that way since the lines were authored.
//
// The markdown stays the AUTHORED SOURCE, because it is reviewed by hand and its table
// is the reviewable artifact. This JSON is a build product of it that lives inside the
// deploy boundary, and `doLines.test.js` fails if the two disagree — so the generated
// file cannot drift from the reviewed one.
//
// Run this after editing the review table, and commit the result.

import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

import { parseReviewTable } from '../lib/counterCards.js';

const __dirname = dirname(fileURLToPath(import.meta.url));
const REVIEW = join(__dirname, '..', '..', 'docs', 'do-lines-review.md');
const OUT = join(__dirname, '..', 'lib', 'doLines.json');

const reviewed = parseReviewTable(readFileSync(REVIEW, 'utf8'));
if (!reviewed.size) {
  console.error('[do-lines] the review table parsed to nothing — refusing to write an empty file.');
  process.exit(1);
}

// Slug -> do line. The `flag` column is review metadata and is deliberately not carried:
// production needs the line, not the notes about drafting it.
const out = {};
for (const slug of [...reviewed.keys()].sort()) {
  const line = String(reviewed.get(slug)?.do || '').trim();
  if (line) out[slug] = line;
}

writeFileSync(OUT, `${JSON.stringify(out, null, 2)}\n`, 'utf8');
console.log(`[do-lines] wrote ${Object.keys(out).length} do lines to lib/doLines.json ✓`);
// Two-line card rule check (docs/CARD-STYLE-SAMPLES.md). Usage:
//   node scripts/twoLineCheck.js [proposals.json ...]   (from server/)
// With proposals ({id: {decision, buying_tips}}), checks them applied to an in-memory KB copy;
// without, checks the KB as it stands. Exit 1 on any violation.
import { readFileSync } from 'node:fs';
import { projectEntry } from '../lib/counterCards.js';
import { lintCard, words } from '../lib/counterCardLint.js';

const kb = JSON.parse(readFileSync(new URL('../kristy_perimeter_kb.json', import.meta.url)));
const doLines = JSON.parse(readFileSync(new URL('../lib/doLines.json', import.meta.url)));
const doFor = (id) => (Array.isArray(doLines) ? doLines.find((d) => d.slug === id || d.id === id)?.do : doLines[id]?.do ?? doLines[id]) || '';
const proposals = Object.assign({}, ...process.argv.slice(2).map((f) => JSON.parse(readFileSync(f, 'utf8'))));
const byId = new Map(kb.entries.map((e) => [e.id, e]));
const FIRST_PERSON = /\b(I|me|my|mine|we|our|us)\b/;
const APPROVED_LONG = new Set(['ground_beef_lean_ratio', 'whole_vs_reduced_fat_milk']);
let bad = 0;
const ids = Object.keys(proposals).length ? Object.keys(proposals) : kb.entries.filter((e) => e.kind !== 'pick').map((e) => e.id);
for (const id of ids) {
  const base = byId.get(id);
  if (!base) { console.log(`${id}: NO_SUCH_ENTRY`); bad++; continue; }
  const e = { ...base, ...(proposals[id] || {}) };
  const out = [];
  const tip0 = (e.buying_tips || [])[0] || '';
  // Devon approved the CARD-STYLE-SAMPLES line 1s verbatim (2026-10-17); "10 words plus the food" lets ground beef run 12.
  if (words(e.decision) > (APPROVED_LONG.has(id) ? 12 : 10)) out.push(`LINE1_LONG ${words(e.decision)}w`);
  const card = projectEntry(e, { doLine: doFor(id) });
  if (card.look_for?.[0] !== tip0) out.push(`LINE2_NOT_FIRST_LOOK_FOR (cautionary wording or authored watch_out?)`);
  if (tip0.length > 90) out.push(`LINE2_LONG ${tip0.length}c`);
  for (const [f, v] of [['decision', e.decision], ['tip0', tip0]]) if (FIRST_PERSON.test(v)) out.push(`FIRST_PERSON ${f}`);
  if (/—/.test(e.decision) || /—/.test(tip0)) out.push('EM_DASH');
  for (const v of lintCard(card) || []) out.push(`${v.code}${v.field ? `[${v.field}]` : ''} ${v.detail || ''}`.trim());
  if (out.length) { bad++; console.log(`${id}: ${out.join(' | ')}`); }
}
console.log(`${ids.length} checked, ${bad} with violations`);
process.exit(bad ? 1 : 0);
/* THE CHECK PASSED BECAUSE IT COULD NOT SEE THE THING — the untracked-file variant.
 *
 *   node scripts/commitGuard.js          (before any commit that claims a feature)
 *
 * TWICE NOW, LOCAL WAS GREEN AND `main` WAS INCOMPLETE, for the same reason: a module was
 * written, imported, tested and committed-around while git had never been told it exists.
 * `git commit -a` does not add untracked files. Neither does `git commit <path>` for a
 * path that was never staged. So the working tree — where every test runs — has the file,
 * and the commit does not.
 *
 * The second and clearest case: `3267c95 The list becomes the trip, and the whole list is
 * free` landed the list matcher and NOT the trips feature. `server/lib/trips.js`,
 * `server/routes/trips.js`, `trips.test.js` and the loop harness stayed untracked for a
 * day under a commit title asserting they had shipped. Nothing caught it, because every
 * check ran against a tree that contained them.
 *
 * This is the same family as the vacuous-assertion rule in CLAUDE.md — `[].every(fn)` is
 * `true`, and a suite that runs against files the commit omits is green for the same kind
 * of reason. In both, the check reports success because the thing it was meant to examine
 * was not in front of it. `nonEmpty` binds at the collection; this binds at the commit.
 *
 * WHAT IT ASSERTS: nothing a commit carries may reference a file git does not track.
 * Import specifiers and path literals are resolved for real — no name matching — so
 * `trips.js` the module is caught and the word "trips" in a comment is not.
 *
 * ─── THE THIRD MEMBER: A REFERENCE IS NOT ALWAYS AN IMPORT ────────────────────────────
 * 2026-08-05: this guard reported "nothing this commit carries references an untracked
 * file" while `server/lib/listRefine.test.js` — eighteen tests, the entire proof of a
 * three-bug fix — sat untracked in a guarded directory. It even PRINTED the count and did
 * nothing with it. The blind spot: nothing imports a test file, so an import graph cannot
 * see one. The guard built to catch a missing test could not see a missing test.
 *
 * Three reference kinds are resolvable and now all three count:
 *
 *   1. IMPORTS AND RELATIVE PATH LITERALS. What this always did.
 *   2. BARE FILENAME LITERALS — `join(__dirname, 'tripFixture.json')`. The browser suites
 *      build every fixture this way and `PATH_LITERAL` required a leading `./`, so
 *      `cartFixture.json`, `composedFixture.json`, `tripFixture.json`, `skim-harness.jsx`
 *      and `shot-harness.jsx` were ALL invisible. A fixture the harness reads by name is
 *      referenced exactly as hard as one it imports.
 *   3. TEST-RUNNER DISCOVERY. `npm test` is `node --test`, which finds files by pattern,
 *      not by import. That pattern IS the reference: a file matching it runs on this
 *      machine and cannot run on any other checkout. Resolved the same way as the rest —
 *      the pattern is the runner's own, so this is not name matching either.
 *
 * WHAT STILL CANNOT BE CAUGHT, stated rather than papered over. A doc or report that
 * nothing reads by path — `docs/LIST-CREATION-AUDIT.md` is the live example — has no
 * resolvable reference anywhere in the tree. Whether it belongs in a commit is a judgment
 * about intent, and static analysis cannot make it. Failing on every untracked file would
 * fire on scratch notes and get this guard ignored, which costs more than it saves. So the
 * remainder is NAMED instead of counted: a human can decide in one glance, and a bare
 * count ("1 untracked in guarded dirs") is precisely what let the test file slide.
 *
 * AND IT SAYS NOTHING ABOUT WHETHER A COMMIT LANDED. It runs before one. On the same day
 * this was written, a commit believed to be pushed had not been made at all — HEAD
 * unmoved, both files still untracked. `git log`/`git status` after the fact is the check
 * for that, and it is not this file's job.
 */

import { execFileSync } from 'node:child_process';
import { existsSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join, resolve, relative } from 'node:path';

const __dirname = dirname(fileURLToPath(import.meta.url));
export const REPO = resolve(__dirname, '..', '..');

/* The directories where an untracked file means an INCOMPLETE COMMIT rather than a stray
   scratch file. Everything here is either shipped or is the thing that verifies what
   ships; a scratchpad note or a local .env is deliberately out of scope. */
/* `docs` is here for one reason and it is not tidiness: `scripts/buildDoLines.js` READS
   `docs/do-lines-review.md`, and that file failing to ship is why every curated `do` line
   was missing from production. A doc the runtime or a build script resolves is a dependency
   whatever its extension. A doc nothing resolves is merely named below, never failed on. */
export const GUARDED = ['server/lib', 'server/routes', 'server/scripts', 'client/src', 'client/test', 'mobile/src', 'docs'];

const CODE = /\.(js|jsx|mjs|cjs|ts|tsx|json)$/;
// Docs count as referenceable because the server READS one: `scripts/buildDoLines.js`
// resolves `docs/do-lines-review.md`, and CLAUDE.md records that exact file failing to
// ship as the reason every curated `do` line was missing in production.
const REFERENCEABLE = /\.(js|jsx|mjs|cjs|ts|tsx|json|md)$/;

/* THE SUITE'S OWN FILES, found by pattern rather than by import.
   `npm test` is `node --test`, which walks for `*.test.js` — no import graph involved. The
   `client/test/*.mjs` suites are invoked by name from CLAUDE.md's Verifying section, and
   everything beside them (`browser.mjs`, `buildFixture.mjs`, the harnesses) is what makes
   them run, so the whole directory counts. Untracked here means: runs on this machine,
   cannot run on any other checkout. */
export const isSuiteFile = (f) => /\.test\.(js|mjs|cjs)$/.test(f) || /^client\/test\/[^/]+\.(mjs|jsx)$/.test(f);

const posix = (p) => p.split('\\').join('/');

const git = (args) => {
  try {
    return execFileSync('git', args, { cwd: REPO, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
  } catch {
    return '';
  }
};

const lines = (s) => s.split('\n').map((l) => l.trim()).filter(Boolean);

/** Files git has never been told about, inside the guarded directories. */
export function untrackedFiles() {
  return lines(git(['ls-files', '--others', '--exclude-standard']))
    .map(posix)
    .filter((f) => REFERENCEABLE.test(f) && GUARDED.some((d) => f.startsWith(`${d}/`)));
}

/**
 * Untracked files the SUITE would run, which nothing imports and no path literal names.
 * This is the case the guard missed: eighteen tests, discovered by pattern, invisible to
 * an import graph. A reference by discovery is still a reference.
 */
export function undiscoveredSuiteFiles() {
  return untrackedFiles().filter(isSuiteFile);
}

/**
 * Everything else untracked in a guarded directory. NOT a failure — whether an unreferenced
 * doc or scratch module belongs in a commit is a judgment about intent that static analysis
 * cannot make. Returned so the CLI can NAME them, because the bare count is what let a test
 * file slide past a human reading this output.
 */
export function unreferencedUntracked() {
  const dangling = new Set(danglingReferences({ mode: stagedFiles().length ? 'staged' : 'tree' }).map((b) => b.resolved));
  const suite = new Set(undiscoveredSuiteFiles());
  return untrackedFiles().filter((f) => !dangling.has(f) && !suite.has(f));
}

/** Files this commit would carry. */
export function stagedFiles() {
  return lines(git(['diff', '--cached', '--name-only', '--diff-filter=ACMR'])).map(posix);
}

/* Tracked source files, for the working-tree mode the test uses.

   DELIBERATELY NOT FILTERED BY `GUARDED`. That list says where an untracked file is a
   problem; it must not also decide what gets READ, and conflating the two put the single
   most important file out of scope. `server/index.js` sits in `server/`, matches none of
   the guarded prefixes, and is exactly the file that mounts a route — it imports
   `./routes/trips.js`, and the first draft of this guard did not look at it. deployBoundary
   makes the same distinction for the same reason: it scans `lib/`, `routes/` AND
   `index.js`. Scanning everything tracked is a few hundred files and cannot have this bug. */
export function trackedSources() {
  return lines(git(['ls-files'])).map(posix).filter((f) => CODE.test(f));
}

/* Relative specifiers only. A bare specifier is a package and resolves through node_modules;
   an absolute one cannot name a repo file portably. Path literals are included because the
   server reads JSON and KB files by path — the same shapes deployBoundary.test.js resolves. */
const SPECIFIER = /(?:from|import|require)\s*\(?\s*['"](\.[^'"]+)['"]/g;
const PATH_LITERAL = /['"](\.\.?\/[^'"]*\.(?:js|jsx|mjs|cjs|ts|tsx|json|md))['"]/g;

/* A BARE FILENAME IS A PATH TOO, and requiring a leading `./` hid every browser fixture.
   `join(__dirname, 'tripFixture.json')` is how all five harnesses reach their fixtures and
   `buildDoLines.js` reaches its markdown; none of them writes `./`. Resolved relative to
   the referencing file's own directory and only reported when it lands on a file git does
   not track, so a bare `'index.js'` in a comment cannot fire unless an untracked
   `index.js` really sits next to it. */
const BARE_LITERAL = /['"]([A-Za-z0-9_][A-Za-z0-9._-]*\.(?:js|jsx|mjs|cjs|ts|tsx|json|md))['"]/g;

/** Resolve a specifier the way node would, returning a repo-relative path or null. */
function resolveSpec(fromFile, spec) {
  const base = resolve(REPO, dirname(fromFile));
  const candidates = [
    resolve(base, spec),
    ...(CODE.test(spec) ? [] : ['.js', '.jsx', '.mjs', '.ts', '.tsx', '/index.js'].map((e) => resolve(base, spec + e))),
  ];
  for (const c of candidates) {
    const rel = posix(relative(REPO, c));
    if (rel.startsWith('..')) continue;
    if (existsSync(c) || REFERENCEABLE.test(rel)) return rel;
  }
  return null;
}

/**
 * Every reference, in `sources`, to a file git does not track.
 *
 * @param {object} [opts]
 * @param {'staged'|'tree'} [opts.mode='staged']
 * @returns {Array<{from:string, specifier:string, resolved:string}>}
 */
export function danglingReferences({ mode = 'staged' } = {}) {
  const untracked = new Set(untrackedFiles());
  if (!untracked.size) return [];

  const sources = (mode === 'staged' ? stagedFiles() : trackedSources()).filter((f) => CODE.test(f));
  const out = [];

  for (const f of sources) {
    // Read what the COMMIT carries, not what the working tree happens to hold — they differ
    // exactly when someone stages a partial change, which is when this matters most.
    let src = '';
    if (mode === 'staged') src = git(['show', `:${f}`]);
    if (!src) {
      const onDisk = join(REPO, f);
      if (!existsSync(onDisk)) continue;
      src = readFileSync(onDisk, 'utf8');
    }

    const seen = new Set();
    for (const re of [SPECIFIER, PATH_LITERAL, BARE_LITERAL]) {
      re.lastIndex = 0;
      let m;
      while ((m = re.exec(src))) {
        const spec = m[1];
        if (seen.has(spec)) continue;
        seen.add(spec);
        const resolved = resolveSpec(f, spec);
        if (resolved && untracked.has(resolved)) out.push({ from: f, specifier: spec, resolved });
      }
    }
  }
  return out;
}

/* ── CLI ── */
if (process.argv[1] && posix(process.argv[1]).endsWith('scripts/commitGuard.js')) {
  const staged = stagedFiles();
  const mode = staged.length ? 'staged' : 'tree';
  const bad = danglingReferences({ mode });
  const suite = undiscoveredSuiteFiles();
  const rest = unreferencedUntracked();

  console.log(`commitGuard: ${mode} mode · ${staged.length} staged · ${untrackedFiles().length} untracked in guarded dirs`);

  if (bad.length) {
    console.error(
      `\n${bad.length} REFERENCE${bad.length > 1 ? 'S' : ''} TO UNTRACKED FILE${bad.length > 1 ? 'S' : ''} — ` +
      `this commit would be green locally and incomplete on main:\n`
    );
    for (const b of bad) console.error(`  ${b.from}\n      references ${b.specifier}  ->  ${b.resolved}  (UNTRACKED)`);
  }

  if (suite.length) {
    console.error(
      `\n${suite.length} SUITE FILE${suite.length > 1 ? 'S' : ''} GIT DOES NOT TRACK — ` +
      `${suite.length > 1 ? 'these run' : 'this runs'} here and nowhere else:\n`
    );
    // Named as a discovery reference, because that is what it is. Nothing imports a test.
    for (const f of suite) console.error(`  ${f}  (found by the runner's own pattern, not by an import)`);
  }

  // NAMED, NEVER COUNTED. A bare count is what this output used to give, and it is what a
  // human reads straight past — which is exactly how eighteen tests stayed untracked.
  if (rest.length) {
    console.log(`\n${rest.length} untracked and unreferenced in a guarded dir. Not a failure; nothing resolves to`);
    console.log('them, so whether they belong in this commit is yours to say:\n');
    for (const f of rest) console.log(`  ${f}`);
  }

  const missing = [...new Set([...bad.map((b) => b.resolved), ...suite])];
  if (!missing.length) {
    console.log('\nnothing this commit carries references an untracked file, and no suite file is missing');
    process.exit(0);
  }
  console.error(`\n  git add ${missing.join(' ')}\n`);
  process.exit(1);
}
/* The list→card match probe. Measures CORRECTNESS, and exits non-zero on a wrong match.
 *
 *   node scripts/listMatchProbe.js
 *
 * ═══ WHAT THE FIRST VERSION MEASURED, AND WHY THE NUMBER WAS HOLLOW ═══
 *
 * The Phase 1 probe reported 71%→83% coverage with ZERO false positives, and both figures
 * were true of what it asked. It asked the wrong thing, twice:
 *
 *   1. ITS FAILURE CLASS WAS ONLY "MATCHED SOMETHING WHEN IT SHOULD HAVE MATCHED NOTHING."
 *      Six items — cereal, dish soap, paper towels, ketchup, pasta sauce, tortillas — were
 *      marked `expect: 'none'`, and a hit on one of those was the only thing counted as a
 *      false positive. Everything else was scored `hit ? pass : miss`. An item that matched
 *      the WRONG CARD counted as a SUCCESS. "Frozen broccoli or green beans" landing on
 *      `beans_dried_vs_canned` — "fill a bag from the bulk bin" on a frozen item — would
 *      have been tallied as one of the 83%.
 *
 *   2. ITS INPUT WAS BARE NOUNS IT INVENTED. Thirty lowercase singles and pairs
 *      ("blueberries", "chicken thighs"), which is what a shopper TYPES. It is not what the
 *      compose flow EMITS: composed rows carry authored PICK names ("Frozen broccoli or
 *      green beans"), a `why` on all 51, and an authored `perimeterId` on 22.
 *
 * So the probe agreed with the mock, which agreed with the harness, which agreed with the
 * browser test — and none of them agreed with the product.
 *
 * ═══ WHAT THIS MEASURES INSTEAD ═══
 *
 * Ground truth, two sources, no hand-maintained expectation list:
 *
 *   AUTHORED   the 22 PICKS carrying a `perimeterId`. That id was chosen by a person and is
 *              claim-locked. Retrieval disagreeing with it is a WRONG MATCH, not a hit.
 *   OVERLAP    for a card reached by retrieval with no authored id, the card must share a
 *              real food word with the item. Zero food overlap is the shape every false
 *              positive in this class has taken — "tuna" reaching a fresh-counter card,
 *              "beans" reaching a dried-beans card, "unpasteurized" reaching a milk card,
 *              and "worth"/"buying" reaching a farmed-fish card in the ask pipeline.
 *
 *   STATE      an item that names canned / tinned / dried attached to a PRODUCE card whose own
 *              text names no state is WRONG. The produce section sells the fresh thing, so a
 *              stateless produce card is about the fresh thing (`cardStates`, listMatch.js),
 *              and "Canned tomatoes" → `produce_ripeness_by_item` told a shopper to smell the
 *              stem end of a tin (API-FINDINGS §17). The probe reads the card's text with the
 *              same STATES regexes and never the matcher's inference — a probe that asks the
 *              matcher whether the matcher is right proves nothing.
 *
 * ═══ TWO POPULATIONS, BECAUSE THE FIRST ONE COVERED THE DOOR NOBODY WALKS THROUGH FIRST ═══
 *
 * Moving off invented bare nouns onto PICKS fixed one blindness by creating another. PICKS
 * are the SEEDED path, where an authored `perimeterId` attaches regardless of aliases. The
 * BUILD path — the one every new shopper takes — has the model emit bare nouns and retrieval
 * is all there is, and this probe was green (37/37, 0 wrong) while five of the first walk's
 * eight rows attached nothing (API-FINDINGS §16, WALK-2026-09-10 W16). So BARE_NOUNS is the
 * second population: what a shopper TYPES, judged by the same two wrong-match rules.
 *
 * A MISS IS REPORTED AND DOES NOT FAIL. Coverage is an authoring backlog — that is what
 * `counter_gaps` is for. A WRONG MATCH FAILS, because a wrong do line is worse than no do
 * line and is the only outcome here that actively misinforms someone in a store.
 */

import { PICKS } from '../lib/list.js';
import { attachCards, cardForItem, entryById, matchItemToCard, matchItemToPick, STATES } from '../lib/listMatch.js';
import { sectionForCategory } from '../lib/counterCards.js';
import { scoreEntries } from '../lib/perimeter.js';

/* Words that describe a STATE, a QUALITY or a package rather than a food. A card sharing
   only these with an item has not matched its subject — which is the whole failure mode. */
const NOT_A_FOOD = new Set([
  'and', 'the', 'for', 'with', 'from', 'any', 'two', 'kinds', 'whatever', 'own',
  'raw', 'plain', 'whole', 'real', 'fresh', 'frozen', 'canned', 'dried', 'dry', 'tinned',
  'ground', 'roasted', 'baby', 'sweet', 'steel', 'cut', 'live', 'culture', 'cultures',
  'grass', 'fed', 'pasture', 'raised', 'wild', 'caught', 'bone', 'bones', 'boneless',
  'unpasteurized', 'pasteurized', 'refrigerated', 'sprouted', 'extra', 'virgin', 'dark',
  'bottle', 'low', 'sugar', 'free', 'salt', 'just', 'season', 'lean', 'light', 'white',
  'best', 'buy', 'buying', 'worth', 'good', 'better', 'vs', 'versus', 'what', 'which',
  'grade', 'grades', 'label', 'labels', 'labeled', 'check', 'read', 'pick', 'picking',
]);

const words = (s) =>
  new Set(
    String(s || '')
      .toLowerCase()
      .match(/[a-z]+/g)
      ?.filter((w) => w.length > 2 && !NOT_A_FOOD.has(w)) || []
  );

const pad = (s, n) => String(s ?? '').padEnd(n);

/* ═══ --universe <path>: K2 coverage over the whole-store universe ═══
   Each row goes through the real attach path (card first, then pick floor). Covered = a card
   or pick attached. `carried` rows are counted apart and are never gaps. Exit 1 only when a
   row's `expect` id is set and a different id attached. Default mode below is untouched. */
const uIdx = process.argv.indexOf('--universe');
if (uIdx > -1) {
  const { readFileSync } = await import('node:fs');
  const path = process.argv[uIdx + 1];
  if (!path) { console.error('--universe needs a path'); process.exit(1); }
  const universe = JSON.parse(readFileSync(path, 'utf8'));
  if (!Array.isArray(universe) || universe.length < 1) { console.error('universe is empty'); process.exit(1); }
  const sections = new Map();
  const carried = [];
  const gaps = [];
  const wrongs = [];
  const missing = [];
  let hasWords = false;
  const attachId = (name) => {
    const r = attachCards({ items: [{ name, source: 'user' }] }, { log: false }).items[0];
    return r.cardSlug || r.pickId || null;
  };
  for (const u of universe) {
    let got;
    if (Array.isArray(u.list_words) && u.list_words.length) {
      hasWords = true;
      let all = true;
      for (const w of u.list_words) {
        const id = attachId(w);
        if (!id) { all = false; missing.push(`${u.item}: ${w}`); } else if (u.expect && id !== u.expect) (all = false), wrongs.push(`${u.item} [${w}]: expected ${u.expect}, got ${id}`);
      }
      got = all ? u.expect || 'list_words' : null;
    } else got = attachId(u.item);
    if (u.mechanism === 'carried') { carried.push({ item: u.item, got }); continue; }
    const s = sections.get(u.section) || { covered: 0, total: 0 };
    s.total += 1;
    if (got) s.covered += 1; else gaps.push(`${u.section}: ${u.item}`);
    sections.set(u.section, s);
    if (u.expect && got && got !== u.expect) wrongs.push(`${u.item}: expected ${u.expect}, got ${got}`);
    if (u.expect && !u.list_words) console.log(`  expect ${pad(u.item, 36)} ${u.expect} -> ${got || '(none)'}`);
  }
  let cov = 0;
  let tot = 0;
  for (const [name, s] of sections) {
    console.log(`${pad(name, 18)} ${s.covered}/${s.total}`);
    cov += s.covered;
    tot += s.total;
  }
  console.log(`${pad('TOTAL', 18)} ${cov}/${tot}`);
  console.log(`carried (not gaps): ${carried.length}, of which attached something: ${carried.filter((c) => c.got).length}`);
  console.log(`\nUNCOVERED (${gaps.length}):`);
  for (const g of gaps) console.log(`  ${g}`);
  if (hasWords) { console.log(`\nMISSING ${missing.length}`); for (const m of missing) console.log(`  ${m}`); }
  if (process.argv.includes('--strict') && missing.length && !wrongs.length) process.exit(1);
  if (wrongs.length) { console.error(`\n${wrongs.length} WRONG:`); for (const w of wrongs) console.error(`  ✗ ${w}`); process.exit(1); }
  process.exit(0);
}

/* ═══ BARE_NOUNS — what a shopper types, with its provenance ═══

   PROVENANCE, checked 2026-09-11. Neither measured input list survives: API-FINDINGS §16
   reports "19/34" and names only the 15 misses; WALK-2026-09-10 W16 reports "16 of 26" and
   names only the 10 misses; `grep -rn` over kristy-ios/docs and KristyUITests finds neither
   list. So this population is everything that IS recorded, in the words it was recorded in —
   it is not a reconstruction of either list and its attach count is not comparable to
   19/34 or 16/26. Extend it from a real list, never from the corpus's own vocabulary. */
const BARE_NOUNS = [
  // API-FINDINGS §16 — the 15 named misses, lowercase as measured.
  'apples', 'carrots', 'broccoli', 'leafy greens', 'spinach', 'bell peppers', 'cucumber',
  'celery', 'zucchini', 'lettuce', 'kale', 'grapes', 'peaches', 'milk', 'garlic',
  // WALK-2026-09-10 W16 — the named misses not already above.
  'lemons', 'frozen peas',
  // KristyUITests/FirstTripWalk — the 8 rows the model emitted from "chicken thighs, rice,
  // sweet potatoes, and produce for lunches and dinners this week", cased as emitted (§16).
  'Sweet potatoes', 'Bone-in, skin-on chicken thighs', 'Brown or jasmine rice', 'Carrots',
  'Broccoli', 'Bell peppers', 'Leafy greens', 'Apples',
  // API-FINDINGS §17 — the wrong match. Attaching it to a produce card is the STATE failure.
  'Canned tomatoes',
  // PLAN-step1-plumbing piece 4 — the bare nouns the hub-rule aliases were authored for.
  'apple', 'peach', 'nectarines', 'plums', 'limes', 'oranges', 'citrus', 'strawberries',
  'strawberry',
  // The head-noun-before-a-qualifier rows (listMatch.js `aliasNamesHead`). Expected:
  // "Peanut butter — …" CORRECT on nut_butter_ingredients (never on "salt", which is in
  // NOT_A_FOOD so a salt match reads WRONG); "Beef or chicken liver" MISS — no card owns liver.
  'Peanut butter — just peanuts and salt', 'Beef or chicken liver',
];

/* The states an ITEM can name that no stateless produce card can answer. `fresh` is not here
   on purpose: a fresh item on a fresh card is the agreeing case. `frozen` is not here because
   the rule was specified for the shelf-stable states (canned / tinned / dried — `tinned` is
   inside STATES.canned); a frozen item on a stateless produce card would be wrong in the same
   way, and adding it here is the same deliberate act as widening STATES. */
const SHELF_STATES = ['canned', 'dried'];

const cardOwnStates = (entry) => {
  const t = ` ${[entry?.title || '', ...(entry?.aliases || [])].join(' ').toLowerCase()} `;
  return new Set(Object.keys(STATES).filter((k) => STATES[k].test(t)));
};

/**
 * OVERLAP and STATE, for a card that retrieval reached with no authored id.
 * Returns `{ verdict, detail }`.
 */
function judgeRetrieved(name, slug, states = SHELF_STATES) {
  const entry = entryById(slug);
  const itemT = ` ${String(name).toLowerCase()} `;
  const named = states.filter((k) => STATES[k].test(itemT));
  if (named.length && sectionForCategory(entry?.category) === 'produce' && cardOwnStates(entry).size === 0) {
    return { verdict: 'WRONG', detail: `attached ${slug}, a produce card naming no state, to an item naming ${named.join('/')}` };
  }
  const itemW = words(name);
  const cardW = new Set([...words(entry?.title), ...(entry?.aliases || []).flatMap((a) => [...words(a)])]);
  const overlap = [...itemW].filter((w) => cardW.has(w));
  if (overlap.length === 0) {
    return { verdict: 'WRONG', detail: `attached ${slug} sharing no food word with "${name}"` };
  }
  return { verdict: 'CORRECT', detail: `on ${overlap.join(', ')}` };
}

const rows = [];
for (const [key, p] of Object.entries(PICKS)) {
  const item = { name: p.name, ...(p.perimeterId ? { perimeterId: p.perimeterId } : {}) };
  const shipped = cardForItem(item);
  const retrieved = matchItemToCard(p.name);
  const top = scoreEntries(p.name, 1)[0];

  let verdict;
  let detail = '';

  if (p.perimeterId) {
    // Ground truth exists. The row must end up on it.
    if (!shipped) {
      verdict = 'DROPPED';
      detail = `authored ${p.perimeterId}, nothing attached`;
    } else if (shipped.slug !== p.perimeterId) {
      verdict = 'WRONG';
      detail = `authored ${p.perimeterId}, attached ${shipped.slug}`;
    } else {
      verdict = 'CORRECT';
      // Worth surfacing: retrieval alone would have disagreed. Not a failure — precedence
      // is doing its job — but it is the count that says how much work precedence is doing.
      if (retrieved && retrieved.slug !== p.perimeterId) detail = `retrieval alone would have said ${retrieved.slug}`;
    }
  } else if (!shipped) {
    verdict = 'MISS';
    detail = top ? `best was ${top.entry.id} at ${top.score}` : 'nothing scored';
  } else {
    ({ verdict, detail } = judgeRetrieved(p.name, shipped.slug));
  }

  rows.push({ key, name: p.name, authored: p.perimeterId || null, slug: shipped?.slug || null, verdict, detail, score: shipped?.score ?? top?.score ?? 0 });
}

// An assertion over an empty collection passes. Bind at the collection.
if (rows.length < 20) {
  console.error(`only ${rows.length} PICKS read — the corpus did not load, and every rate below would be meaningless`);
  process.exit(1);
}

const bare = [];
for (const name of BARE_NOUNS) {
  const hit = matchItemToCard(name);
  const top = scoreEntries(name, 1)[0];
  let verdict;
  let detail = '';
  if (!hit) {
    verdict = 'MISS';
    detail = top ? `best was ${top.entry.id} at ${top.score}` : 'nothing scored';
  } else {
    ({ verdict, detail } = judgeRetrieved(name, hit.slug));
  }
  bare.push({ name, slug: hit?.slug || null, verdict, detail });
}
// Same guard, same reason: a population that did not load scores nothing wrong.
if (bare.length < 20) {
  console.error(`only ${bare.length} bare nouns — the population did not load`);
  process.exit(1);
}

/* ═══ REALISTIC_26 — the plan's D4 list, verbatim, through the REAL attach order ═══

   Card first, then the pick floor, on the corpus as committed (zero picks until Piece 3 lands,
   so today `pick` is 0 everywhere and the line reads the same as the held baseline: 19/26).
   Every row is food, so `guided/food` is guided/26.

   WRONG, exits non-zero:
     - a pick on a row a card owns (the order is cards first; a pick beside a slug is the
       floor running before the ceiling)
     - a pick sharing no food word with the row (that is a pick on a row that is not its
       subject — the non-food case, judged the same way a card is)
     - a fresh (stateless produce) pick on a canned / frozen / dried row
   MISS only reports. */
const REALISTIC_26 = [
  'apples', 'bananas', 'strawberries', 'carrots', 'broccoli', 'bell peppers', 'leafy greens',
  'spinach', 'lemons', 'garlic', 'onions', 'sweet potatoes', 'avocados', 'eggs', 'milk',
  'greek yogurt', 'butter', 'cheddar cheese', 'chicken thighs', 'ground beef', 'salmon',
  'brown rice', 'oats', 'olive oil', 'canned tomatoes', 'frozen peas',
];
const PICK_STATES = ['canned', 'frozen', 'dried'];
const realistic = [];
for (const name of REALISTIC_26) {
  // The REAL attach, not a re-implementation of its order: a probe that scores cards first
  // itself would print CORRECT with the floor flipped in attachCards.
  const [row] = attachCards({ items: [{ name, source: 'user' }] }, { log: false }).items;
  const card = row.cardSlug || null;
  const pick = row.pickId || null;
  let verdict = 'MISS';
  let detail = '';
  let via = '(none)';
  // Two shapes of the floor running first: the pick beside the slug, or the pick INSTEAD of
  // the slug (an early return drops the card). Both are WRONG; only the second is what a
  // flipped order actually produces, so a row with a pick is also checked against the card
  // the corpus owns for it.
  const owned = pick ? matchItemToCard(name)?.slug : null;
  if (pick && (card || owned)) {
    verdict = 'WRONG';
    detail = `pick ${pick} on a row card ${card || owned} owns — the floor ran before the ceiling`;
    via = `${card || owned}+pick:${pick}`;
  } else if (card) {
    ({ verdict, detail } = judgeRetrieved(name, card));
    via = card;
    const lost = matchItemToPick(name);
    if (lost) detail += ` (pick ${lost.id} also matched and correctly lost)`;
  } else if (pick) {
    ({ verdict, detail } = judgeRetrieved(name, pick, PICK_STATES));
    via = `pick:${pick}`;
  }
  realistic.push({ name, slug: via === '(none)' ? null : via, verdict, detail, pick: !!pick });
}
// A named card the corpus owns must be the one attached; a neighbour stealing the row is WRONG.
// `chicken_cuts_basics` carries the bare alias `chicken`, so the rotisserie row is the hub test.
const OWNED_BY = { 'rotisserie chicken': 'rotisserie_chicken', 'milk': 'whole_vs_reduced_fat_milk', 'whole milk': 'whole_vs_reduced_fat_milk', 'a gallon of milk': 'whole_vs_reduced_fat_milk' };
for (const [name, slug] of Object.entries(OWNED_BY)) {
  const [row] = attachCards({ items: [{ name, source: 'user' }] }, { log: false }).items;
  const got = row.cardSlug || null;
  const verdict = got === slug ? 'CORRECT' : got ? 'WRONG' : 'MISS';
  console.log(`OWNED  ${verdict.padEnd(7)} "${name}" → ${got || '(none)'} (owner ${slug})`);
  if (verdict === 'WRONG') process.exit(1);
}
if (realistic.length !== 26) {
  console.error(`REALISTIC_26 has ${realistic.length} rows — the population did not load`);
  process.exit(1);
}

// Compound rows that carry a pick's bare noun and are a different food. Expected BARE: a pick
// here is the floor attaching a raw-milk line to oat milk. Only an explicitly authored
// compound owner may attach a card. Mirrored in pickReach.test.js COMPOUND_ROWS.
const COMPOUND_ROWS = [
  'oat milk', 'coconut milk', 'milk chocolate', 'corn tortillas', 'corn chips', 'corn flakes',
  'garlic powder', 'garlic bread', 'lemon juice', 'juice boxes', 'carrot cake', 'basil pesto',
  'eggplant parm', 'broccoli slaw',
];
// Build 4 gives these compounds their own cards; the milk/corn picks still lose.
const COMPOUND_OWNERS = { 'oat milk': 'oat_milk', 'corn tortillas': 'tortillas' };
const compound = COMPOUND_ROWS.map((name) => {
  const row = attachCards({ items: [{ name, source: 'user' }] }, { log: false }).items[0];
  const got = row.cardSlug || row.pickId || null;
  const expected = COMPOUND_OWNERS[name] || null;
  const correct = got === expected && !row.pickId;
  return { name, slug: got, verdict: correct ? 'CORRECT' : 'WRONG', detail: expected ? `owner ${expected}, no pick` : (got ? `attached ${got} to an unowned compound row` : 'bare, as it should be') };
});
const compoundWrong = compound.filter((r) => r.verdict === 'WRONG');
// Ordinary modified rows — a pick MUST land. A miss here is the coverage rule over-reaching.
const MODIFIED_ROWS = [
  'organic carrots', 'fresh basil', 'fresh cilantro', 'ripe mangoes', 'organic garlic',
  'whole carrots', 'large cucumbers',
  // P4 — the six WALK-2026-09-10 staple misses, in list wording. Deli turkey lands the
  // deli card; rotisserie chicken lands chicken_cuts_basics through its bare `chicken`
  // alias (the card path owns every `… chicken` row, so it cannot be a pick — pickReach
  // fails one that tries); the other four land picks.
  'Rotisserie chicken', 'Deli turkey', 'Firm tofu', 'Lamb chops', 'Celery', 'Italian sausage',
];
const modified = MODIFIED_ROWS.map((name) => {
  const row = attachCards({ items: [{ name, source: 'user' }] }, { log: false }).items[0];
  const got = row.pickId || row.cardSlug || null;
  return { name, slug: got, verdict: got ? 'CORRECT' : 'WRONG', detail: got ? (row.pickId ? `pick ${row.pickId}` : `card ${row.cardSlug}`) : 'bare — the coverage rule ate an inert modifier' };
});
const modifiedWrong = modified.filter((r) => r.verdict === 'WRONG');
// A modifier that makes a DIFFERENT product — a pick here is WRONG, a card is fine. Mirrored
// in pickReach.test.js WRONG_FOOD_ROWS.
const WRONG_FOOD_ROWS = [
  // `sweet potatoes` lands produce_root_vegetables (a card) since P2 — a card here is fine.
  'baby corn', 'green garlic', 'baby broccoli', 'sweet potatoes', 'green onions', 'red onions',
  'whole chicken',
];
const wrongFood = WRONG_FOOD_ROWS.map((name) => {
  const row = attachCards({ items: [{ name, source: 'user' }] }, { log: false }).items[0];
  const got = row.pickId || null;
  return { name, slug: got || row.cardSlug || null, verdict: got ? 'WRONG' : 'CORRECT', detail: got ? `pick ${got} on a different product` : (row.cardSlug ? `card ${row.cardSlug}, no pick` : 'bare, no pick') };
});
const wrongFoodWrong = wrongFood.filter((r) => r.verdict === 'WRONG');

const by = (v) => rows.filter((r) => r.verdict === v);
const correct = by('CORRECT');
const wrong = by('WRONG');
const dropped = by('DROPPED');
const miss = by('MISS');
const attached = rows.filter((r) => r.slug);

console.log('\n═══════════ EVERY PICK ═══════════');
for (const r of rows) {
  const mark = { CORRECT: ' ', WRONG: '✗', DROPPED: '✗', MISS: '·' }[r.verdict];
  console.log(`  ${mark} ${pad(r.verdict, 8)} ${pad(r.name, 40)} ${pad(r.slug || '(none)', 30)} ${r.detail}`);
}

console.log('\n═══════════ CORRECTNESS ═══════════');
console.log(`  picks                    : ${rows.length}`);
console.log(`  attached a card          : ${attached.length}`);
console.log(`  CORRECT                  : ${correct.length}`);
console.log(`  WRONG (fails this probe) : ${wrong.length}`);
console.log(`  DROPPED authored card    : ${dropped.length}`);
console.log(`  miss, no card (backlog)  : ${miss.length}`);
console.log(
  `\n  WRONG-MATCH RATE ON ATTACHED ROWS: ` +
  `${attached.length ? ((wrong.length / attached.length) * 100).toFixed(1) : '0.0'}% ` +
  `(${wrong.length}/${attached.length})`
);

const authored = rows.filter((r) => r.authored);
const authoredOk = authored.filter((r) => r.verdict === 'CORRECT');
console.log(
  `  AGAINST AUTHORED GROUND TRUTH    : ${authoredOk.length}/${authored.length} correct ` +
  `(${(((authored.length - authoredOk.length) / authored.length) * 100).toFixed(1)}% wrong)`
);
const rescued = correct.filter((r) => r.authored && r.detail.startsWith('retrieval alone'));
console.log(`  rows precedence is carrying      : ${rescued.length} (retrieval alone would have attached a different card)`);

const bareWrong = bare.filter((r) => r.verdict === 'WRONG');
const bareMiss = bare.filter((r) => r.verdict === 'MISS');
const bareAttached = bare.filter((r) => r.slug);

console.log('\n═══════════ EVERY BARE NOUN (what a shopper types) ═══════════');
for (const r of bare) {
  const mark = { CORRECT: ' ', WRONG: '✗', MISS: '·' }[r.verdict];
  console.log(`  ${mark} ${pad(r.verdict, 8)} ${pad(r.name, 40)} ${pad(r.slug || '(none)', 30)} ${r.detail}`);
}
console.log(`\n  BARE NOUNS ATTACHED              : ${bareAttached.length}/${bare.length}`);
console.log(`  WRONG (fails this probe)         : ${bareWrong.length}`);
console.log(`  miss, no card (backlog)          : ${bareMiss.length}`);

const realWrong = realistic.filter((r) => r.verdict === 'WRONG');
const realGuided = realistic.filter((r) => r.slug);
console.log('\n═══════════ REALISTIC_26 (the plan\'s list, real attach order) ═══════════');
for (const r of realistic) {
  const mark = { CORRECT: ' ', WRONG: '✗', MISS: '·' }[r.verdict];
  console.log(`  ${mark} ${pad(r.verdict, 8)} ${pad(r.name, 40)} ${pad(r.slug || '(none)', 30)} ${r.detail}`);
}
console.log(`\n  guided/food                      : ${realGuided.length}/${realistic.length}`);
console.log(`  of which by a pick               : ${realistic.filter((r) => r.pick).length}`);
console.log(`  WRONG (fails this probe)         : ${realWrong.length}`);
console.log(`  miss, no guidance (backlog)      : ${realistic.length - realGuided.length}`);

console.log('\n═══════════ COMPOUND_ROWS (carry a pick noun, expected bare) ═══════════');
for (const r of compound) {
  const mark = { CORRECT: ' ', WRONG: '✗' }[r.verdict];
  console.log(`  ${mark} ${pad(r.verdict, 8)} ${pad(r.name, 40)} ${pad(r.slug || '(none)', 30)} ${r.detail}`);
}
console.log(`\n  WRONG (fails this probe)         : ${compoundWrong.length}/${compound.length}`);

console.log('\n═══════════ MODIFIED_ROWS (inert modifier + pick noun, must land) ═══════════');
for (const r of modified) {
  const mark = { CORRECT: ' ', WRONG: '✗' }[r.verdict];
  console.log(`  ${mark} ${pad(r.verdict, 8)} ${pad(r.name, 40)} ${pad(r.slug || '(none)', 30)} ${r.detail}`);
}
console.log(`\n  WRONG (fails this probe)         : ${modifiedWrong.length}/${modified.length}`);

